    if kind == "SEQ":
        if not isinstance(value, list):
            raise TypeError(f"expected a list, got {value!r}")
        return [_decode(inner, v) for v in value]
    if kind == "TUPLE":
        if not isinstance(value, list) or len(value) != len(inner):
            raise TypeError(f"expected an array of {len(inner)}, got {value!r}")
        return tuple(_decode(f, v) for f, v in zip(inner, value))
